contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run will call Put on c with an amount and unlock time, and assert post-conditions
    function run(uint unlockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // read before-values via public getters
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // perform the call, capture whether it reverted
        bool reverted = false;
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If the Put call did not revert then the holder.balance must have increased by amount
        // and the contract's Ether balance must have increased by amount. If it reverted, no guarantee.
        assert(reverted || (afterBalance == beforeBalance + amount && afterContractBal == beforeContractBal + amount));
    }

    // allow receiving Ether when other contracts send to this test
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to Collect _am after ensuring this test contract has at least MinSum recorded and enough unlocked balance.
    // We take parameters to drive Put and Collect. The function is payable so it can fund Put.
    function run(uint putUnlockTime, uint putAmount, uint collectAmount) public payable {
        // Must be able to fund the Put call
        require(address(this).balance >= putAmount);

        // Read MinSum from c (public)
        uint minSum = c.MinSum();

        // Ensure we attempt a Put that makes this test contract have recorded balance >= MinSum
        // If putAmount < minSum we still allow but then Collect is expected to fail (or do nothing).
        // First read before-values
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Perform Put to deposit funds and set unlockTime
        bool putReverted = false;
        try c.Put{value: putAmount}(putUnlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read after the Put
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // Now attempt Collect of collectAmount
        bool collectReverted = false;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read final values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Collect did not revert then the following must hold:
        //  - The contract's ether balance decreased by exactly collectAmount
        //  - The recorded holder balance decreased by exactly collectAmount
        // Otherwise we don't assert anything about state changes.
        assert(collectReverted || (afterContractBal + collectAmount == midContractBal && afterBalance + collectAmount == midBalance));
    }

    // Accept Ether so that Put can send Ether back or other transfers can occur
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We drive Put and Collect. Parameters: putUnlockTime, putAmount to fund Put; collectAmount to attempt Collect.
    // The function is payable so the test can provide Ether for Put.
    function run(uint putUnlockTime, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);

        // Read initial recorded holder info and contract balance
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Perform Put (may revert) to possibly increase our recorded balance in c
        bool putReverted = false;
        try c.Put{value: putAmount}(putUnlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read mid-state after Put
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // Attempt Collect; record whether it reverted
        bool collectReverted = false;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read final state
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Collect succeeded then the recorded balance must not have increased,
        // and the contract's ether balance must have decreased by at least the decrease in recorded balance.
        // This rule permits extra decreases in contract balance (e.g., due to failed internal transfers) but
        // enforces that recorded balance cannot increase due to Collect and that Ether doesn't vanish relative to recorded decrease.
        assert(collectReverted || (afterBalance <= midBalance && (midBalance - afterBalance) <= (midContractBal - afterContractBal)));
    }

    // Accept Ether so received Collect transfers can be handled if needed
    receive() external payable {}
}

